/* ---------------------------------------------------------------------------
   RESTORE the RRD Movidor parameters + options after an import wiped them.

   A parameter CSV import replaces the whole set: control names missing from
   the file are deleted, together with their options. Rules, rule conditions,
   defaults and validations are keyed by ControlName text (no FK to ParamID),
   so they SURVIVED and are deliberately left alone here.

   This restores dbo.uCfgParameters + dbo.uCfgParameterOptions only.
   Re-runnable. It does NOT touch uCfgDefaults, uCfgRules or uCfgRuleConditions.
--------------------------------------------------------------------------- */

/* AUTO-GENERATED from the Python dicts by db/seed_movidor.py. Re-runnable. */
SET NOCOUNT ON;

IF NOT EXISTS (SELECT 1 FROM dbo.uCfgConfigurators WHERE PartID = N'RRD-MOVIDOR-TEMPLATE')
DECLARE @Cfg INT = (SELECT TOP 1 CfgID FROM dbo.uCfgConfigurators WHERE PartID = N'RRD-MOVIDOR-TEMPLATE');
DECLARE @P INT;

-- Clear this configurator's existing definition (idempotent re-run)
DELETE o FROM dbo.uCfgParameterOptions o JOIN dbo.uCfgParameters p ON o.ParamID = p.ParamID WHERE p.CfgID = @Cfg;
DELETE FROM dbo.uCfgParameters WHERE CfgID = @Cfg;

-- Parameters (from movidor_control_names.py)

-- Options (from movidor_option_registery.py, matched to Movidor controls)
